import asyncio


def configure(provider):
    return {
        'lock': asyncio.Lock(),
        'remaining': provider.s.limit,
    }


async def integrate(provider, job, context):
    s = provider.s
    margin = 0.001
    key = 'tempo:' + str(job)

    async def acquire():
        async with context['lock']:
            if context['remaining'] > 0:
                context['remaining'] -= 1
                return
            if s.quota_mode == 'fixed':
                # A full relative window is safe regardless of epoch offset.
                await asyncio.sleep((s.window + margin) * s.scale)
                context['remaining'] = s.limit - 1
            else:
                # After the initial burst, reserve one refill at a time.
                await asyncio.sleep((s.window / s.limit + margin) * s.scale)

    async def run():
        failures = 0
        while True:
            await acquire()
            try:
                response = await provider.post(job, idempotency_key=key)
            except (OSError, asyncio.TimeoutError):
                failures += 1
                await asyncio.sleep(min(2.0, 0.1 * 2 ** min(failures, 5)) * s.scale)
                continue
            if response.status == 200:
                return True
            if response.status == 429:
                # Serialize the cooldown with future quota reservations.
                async with context['lock']:
                    await asyncio.sleep((max(0.0, response.retry_after) + margin) * s.scale)
                continue
            if response.status == 408 or 500 <= response.status < 600:
                failures += 1
                await asyncio.sleep(min(2.0, 0.1 * 2 ** min(failures, 5)) * s.scale)
                continue
            return False

    try:
        return await asyncio.wait_for(run(), s.deadline * s.scale)
    except asyncio.TimeoutError:
        return False
